find . -print | sed -e 's/^\.\///' | sed -e 's|/|\\n|g' | awk '{
    dir = $1;
    if (dir == "") {
        print "";
        next;
    }
    # Count depth by counting slashes
    depth = 0;
    for (i = 1; i <= length(dir); i++) {
        if (substr(dir, i, 1) == "/") {
            depth++;
        }
    }
    # Remove trailing slash if present for cleaner output
    if (substr(dir, length(dir), 1) == "/") {
        dir = substr(dir, 1, length(dir) - 1);
    }
    # Print the path with indentation based on depth
    indent = "";
    for (i = 0; i < depth; i++) {
        indent = indent "  ";
    }
    print indent dir;
}' > tree.json

mkdir -p dst_dir
rsync -av --exclude='*.tmp' src_dir/ dst_dir/
find dst_dir/ -type f -not -path '*/.*' -not -name '.*' -not -path '*/.*' -not -name '*.tmp' -print -exec rm {} \;
